const transitionBooking = `-- name: TransitionBooking :one
UPDATE bookings
SET status = $1,
    cancel_reason = COALESCE($2, cancel_reason),
    payment_due_at = COALESCE($3, payment_due_at)
WHERE id = $4 AND status = $5 AND version = $6
RETURNING id, status, version, status_changed_at
`

type TransitionBookingParams struct {
	ToStatus     BookingStatus `json:"to_status"`
	CancelReason *string       `json:"cancel_reason"`
	PaymentDueAt *time.Time    `json:"payment_due_at"`
	ID           uuid.UUID     `json:"id"`
	FromStatus   BookingStatus `json:"from_status"`
	Version      int32         `json:"version"`
}

type TransitionBookingRow struct {
	ID              uuid.UUID     `json:"id"`
	Status          BookingStatus `json:"status"`
	Version         int32         `json:"version"`
	StatusChangedAt time.Time     `json:"status_changed_at"`
}

// Compare-and-set on status AND version: a stale caller gets no row.
func (q *Queries) TransitionBooking(ctx context.Context, arg TransitionBookingParams) (TransitionBookingRow, error) {
	row := q.db.QueryRow(ctx, transitionBooking,
		arg.ToStatus,
		arg.CancelReason,
		arg.PaymentDueAt,
		arg.ID,
		arg.FromStatus,
		arg.Version,
	)
	var i TransitionBookingRow
	err := row.Scan(
		&i.ID,
		&i.Status,
		&i.Version,
		&i.StatusChangedAt,
	)
	return i, err
}
